const escapeHtml = value => String(value ?? '').replace(/[&<>"']/g, char => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[char]));
const activeAssignments = () => state.assignments.filter(row => row.status === 'active');
const statusCount = status => state.incidents.filter(row => row.status === status).length;
const notify = (message, tone = 'success') => {
  const toast = document.createElement('div'); toast.className = `toast ${tone}`; toast.textContent = translate(message);
  $('#toast-region').append(toast); setTimeout(() => toast.remove(), 4200);
};
async function api(path, options = {}) {
  const response = await fetch(`/api${path}`, {method: options.method || 'GET', headers: {'Content-Type':'application/json', ...(options.key ? {'Idempotency-Key':options.key} : {})}, body: options.body ? JSON.stringify(options.body) : undefined});
  const result = await response.json();
  if (!response.ok) throw new Error(result.error?.message || 'The request could not be completed');
  return result;
}
async function refresh() { state = await api('/state'); render(); syncSimulationTimer(); }
