function metric(label, value, foot = '', tone = '') { return `<div class="metric"><div class="metric-label">${label}</div><div class="metric-value">${value}</div>${foot ? `<div class="metric-foot ${tone}">${foot}</div>` : ''}</div>`; }
function sectionHead(title, meta = '') { return `<div class="section-head"><div class="section-title">${title}</div><div class="section-meta">${meta}</div></div>`; }
function incidentRows(rows) {
  if (!rows.length) return `<tr><td colspan="5"><div class="blank-slate"><b>No matching requests</b>New incident reports will appear here.</div></td></tr>`;
  return rows.map(item => `<tr><td><div class="incident-name">${escapeHtml(item.title)}</div><div class="incident-id">${escapeHtml(item.id)} · ${escapeHtml(item.neighborhood || 'Unassigned area')}</div></td><td><span class="severity ${item.severity>=5?'critical':item.severity<=2?'low':''}">${['','Low','Moderate','Elevated','High','Critical'][item.severity]}</span></td><td><span class="priority-value">${Number(item.priority).toFixed(0)}</span></td><td><span class="status ${item.status}">${escapeHtml(item.status.replace('_',' '))}</span></td><td>${item.people} people</td></tr>`).join('');
}
